@Test(dataProvider = "recoveryLoadBalanceInput")
public void testRecoveryAndLoadBalance(String stateModelDef, int errorOrRecoveryPartitionThresholdForLoadBalance, Map<String, Map<String, Map<String, String>>> stateMapping) {
    System.out.println("START TestRecoveryLoadBalance at " + new Date(System.currentTimeMillis()));
    String resourcePrefix = "resource";
    int nResource = 1;
    int nPartition = 2;
    int nReplica = 3;
    Set<String> resourceSet = new HashSet<>();
    for (int i = 0; i < nResource; i++) {
        resourceSet.add(resourcePrefix + "_" + i);
    }
    preSetup(StateTransitionThrottleConfig.RebalanceType.RECOVERY_BALANCE, resourceSet, nReplica, nReplica, stateModelDef);
    _clusterConfig.setErrorOrRecoveryPartitionThresholdForLoadBalance(errorOrRecoveryPartitionThresholdForLoadBalance);
    setClusterConfig(_clusterConfig);
    event.addAttribute(AttributeName.RESOURCES.name(), getResourceMap(resourceSet.toArray(new String[resourceSet.size()]), nPartition, stateModelDef));
    event.addAttribute(AttributeName.RESOURCES_TO_REBALANCE.name(), getResourceMap(resourceSet.toArray(new String[resourceSet.size()]), nPartition, stateModelDef));
    event.addAttribute(AttributeName.ControllerDataProvider.name(), new ResourceControllerDataProvider());
    // Initialize bestpossible state and current state
    BestPossibleStateOutput bestPossibleStateOutput = new BestPossibleStateOutput();
    CurrentStateOutput currentStateOutput = new CurrentStateOutput();
    IntermediateStateOutput expectedResult = new IntermediateStateOutput();
    for (String resource : resourceSet) {
        IdealState is = accessor.getProperty(accessor.keyBuilder().idealStates(resource));
        setSingleIdealState(is);
        Map<String, List<String>> partitionMap = new HashMap<>();
        for (int p = 0; p < nPartition; p++) {
            Partition partition = new Partition(resource + "_" + p);
            // Set input
            for (int r = 0; r < stateMapping.get(partition.toString()).get(CURRENT_STATE).size(); r++) {
                String instanceName = HOSTNAME_PREFIX + r;
                currentStateOutput.setCurrentState(resource, partition, instanceName, stateMapping.get(partition.toString()).get(CURRENT_STATE).get(instanceName));
            }
            for (int r = 0; r < stateMapping.get(partition.toString()).get(BEST_POSSIBLE_STATE).size(); r++) {
                String instanceName = HOSTNAME_PREFIX + r;
                bestPossibleStateOutput.setState(resource, partition, instanceName, stateMapping.get(partition.toString()).get(BEST_POSSIBLE_STATE).get(instanceName));
            }
            for (int r = 0; r < stateMapping.get(partition.toString()).get(EXPECTED_STATE).size(); r++) {
                String instanceName = HOSTNAME_PREFIX + r;
                expectedResult.setState(resource, partition, instanceName, stateMapping.get(partition.toString()).get(EXPECTED_STATE).get(instanceName));
            }
            // Set partitionMap
            for (int r = 0; r < nReplica; r++) {
                String instanceName = HOSTNAME_PREFIX + r;
                partitionMap.put(partition.getPartitionName(), Collections.singletonList(instanceName));
            }
        }
        bestPossibleStateOutput.setPreferenceLists(resource, partitionMap);
    }
    event.addAttribute(AttributeName.BEST_POSSIBLE_STATE.name(), bestPossibleStateOutput);
    event.addAttribute(AttributeName.CURRENT_STATE.name(), currentStateOutput);
    runStage(event, new ReadClusterDataStage());
    runStage(event, new IntermediateStateCalcStage());
    IntermediateStateOutput output = event.getAttribute(AttributeName.INTERMEDIATE_STATE.name());
    for (String resource : resourceSet) {
        // For debugging purposes
        // Object map1 = output.getPartitionStateMap(resource).getStateMap();
        // Object map2 = expectedResult.getPartitionStateMap(resource).getStateMap();
        // Note Assert.assertEquals won't work. If "actual" is an empty map, it won't compare
        // anything.
        Assert.assertTrue(output.getPartitionStateMap(resource).getStateMap().equals(expectedResult.getPartitionStateMap(resource).getStateMap()));
    }
    System.out.println("END TestRecoveryLoadBalance at " + new Date(System.currentTimeMillis()));
}

