@Test(dependsOnMethods = "testTargetExternalViewWithoutEnable")
public void testExternalViewDiffFromTargetExternalView() throws Exception {
    ClusterConfig clusterConfig = _configAccessor.getClusterConfig(CLUSTER_NAME);
    clusterConfig.enableTargetExternalView(true);
    clusterConfig.setPersistBestPossibleAssignment(true);
    _configAccessor.setClusterConfig(CLUSTER_NAME, clusterConfig);
    Thread.sleep(2000);
    RoutingTableProvider externalViewProvider = new RoutingTableProvider(_manager, PropertyType.EXTERNALVIEW);
    final RoutingTableProvider targetExternalViewProvider = new RoutingTableProvider(_manager, PropertyType.TARGETEXTERNALVIEW);
    try {
        // ExternalView should not contain any MASTERS
        // TargetExternalView should contain MASTERS same as the partition number
        Set<InstanceConfig> externalViewMasters = externalViewProvider.getInstancesForResource(WorkflowGenerator.DEFAULT_TGT_DB, "MASTER");
        Assert.assertEquals(externalViewMasters.size(), 0);
        final Set<InstanceConfig> targetExternalViewMasters = new HashSet<>();
        Assert.assertTrue(TestHelper.verify(new TestHelper.Verifier() {

            @Override
            public boolean verify() {
                targetExternalViewMasters.clear();
                targetExternalViewMasters.addAll(targetExternalViewProvider.getInstancesForResource(WorkflowGenerator.DEFAULT_TGT_DB, "MASTER"));
                return targetExternalViewMasters.size() == NUM_NODES;
            }
        }, 3000));
        // TargetExternalView MASTERS mapping should exactly match IdealState MASTERS mapping
        Map<String, Map<String, String>> stateMap = _gSetupTool.getClusterManagementTool().getResourceIdealState(CLUSTER_NAME, WorkflowGenerator.DEFAULT_TGT_DB).getRecord().getMapFields();
        Set<String> idealMasters = new HashSet<>();
        Set<String> targetMasters = new HashSet<>();
        for (Map<String, String> instanceMap : stateMap.values()) {
            for (String instance : instanceMap.keySet()) {
                if (instanceMap.get(instance).equals("MASTER")) {
                    idealMasters.add(instance);
                }
            }
        }
        for (InstanceConfig instanceConfig : targetExternalViewMasters) {
            targetMasters.add(instanceConfig.getInstanceName());
        }
        Assert.assertTrue(idealMasters.equals(targetMasters));
    } finally {
        externalViewProvider.shutdown();
        targetExternalViewProvider.shutdown();
    }
}

@Test
public void testPeriodicRefresh() throws InterruptedException {
    // Wait so that initial refreshes finish (not triggered by periodic refresh timer)
    Thread.sleep(1000L);
    // Test short refresh
    int prevRefreshCount = _routingTableProvider.getRefreshCount();
    // Wait for one timer duration
    Thread.sleep(1000L);
    // The timer should have gone off, incrementing the refresh count
    Assert.assertEquals(_routingTableProvider.getRefreshCount(), prevRefreshCount + 1);
    // Test no periodic refresh
    prevRefreshCount = _routingTableProviderNoPeriodicRefresh.getRefreshCount();
    // Wait
    Thread.sleep(2000);
    // The timer should NOT have gone off, the refresh count must stay the same
    Assert.assertEquals(_routingTableProviderNoPeriodicRefresh.getRefreshCount(), prevRefreshCount);
    // Test long periodic refresh
    prevRefreshCount = _routingTableProviderLongPeriodicRefresh.getRefreshCount();
    // Wait
    Thread.sleep(2000);
    // The timer should NOT have gone off yet, the refresh count must stay the same
    Assert.assertEquals(_routingTableProviderLongPeriodicRefresh.getRefreshCount(), prevRefreshCount);
    // Call shutdown to make sure they are shutting down properly
    _routingTableProvider.shutdown();
    _routingTableProviderNoPeriodicRefresh.shutdown();
    _routingTableProviderLongPeriodicRefresh.shutdown();
}

