@Test
public void testTaskNotStarted() throws InterruptedException {
    final String BLOCK_WORKFLOW_NAME = "blockWorkflow";
    final String TIMEOUT_WORKFLOW_NAME = "timeoutWorkflow";
    final String DB_NAME = WorkflowGenerator.DEFAULT_TGT_DB;
    final String TIMEOUT_JOB_1 = "timeoutJob1";
    final String TIMEOUT_JOB_2 = "timeoutJob2";
    // 50 blocking tasks
    JobConfig.Builder blockJobBuilder = new JobConfig.Builder().setWorkflow(BLOCK_WORKFLOW_NAME).setTargetResource(DB_NAME).setTargetPartitionStates(Sets.newHashSet(MasterSlaveSMD.States.MASTER.name())).setCommand(MockTask.TASK_COMMAND).setNumConcurrentTasksPerInstance(_numPartitions);
    Workflow.Builder blockWorkflowBuilder = new Workflow.Builder(BLOCK_WORKFLOW_NAME).addJob("blockJob", blockJobBuilder);
    _driver.start(blockWorkflowBuilder.build());
    int numOfParticipantThreads = 40;
    Assert.assertTrue(TaskTestUtil.pollForAllTasksBlock(_manager.getHelixDataAccessor(), _participants[0].getInstanceName(), numOfParticipantThreads, 10000));
    // Now, the HelixTask threadpool is full and blocked by blockJob.
    // New tasks assigned to the instance won't be assigned at all.
    // 2 timeout jobs, first one timeout, but won't block the second one to run, the second one also timeout.
    JobConfig.Builder timeoutJobBuilder = new JobConfig.Builder().setWorkflow(TIMEOUT_WORKFLOW_NAME).setTargetResource(DB_NAME).setTargetPartitionStates(Sets.newHashSet(MasterSlaveSMD.States.MASTER.name())).setCommand(MockTask.TASK_COMMAND).setNumConcurrentTasksPerInstance(_numPartitions).setTimeout(// Wait a bit so that tasks are already assigned to the job (and will be cancelled)
    3000);
    WorkflowConfig.Builder timeoutWorkflowConfigBuilder = new WorkflowConfig.Builder(TIMEOUT_WORKFLOW_NAME).setFailureThreshold(// workflow ignores first job's timeout and schedule second job and succeed.
    1);
    Workflow.Builder timeoutWorkflowBuilder = new Workflow.Builder(TIMEOUT_WORKFLOW_NAME).setWorkflowConfig(timeoutWorkflowConfigBuilder.build()).addJob(TIMEOUT_JOB_1, // job 1 timeout, but won't block job 2
    timeoutJobBuilder);
    // ignore first job's timeout
    timeoutJobBuilder.setIgnoreDependentJobFailure(true);
    // job 2 also timeout
    timeoutWorkflowBuilder.addJob(TIMEOUT_JOB_2, timeoutJobBuilder).addParentChildDependency(TIMEOUT_JOB_1, TIMEOUT_JOB_2);
    _driver.start(timeoutWorkflowBuilder.build());
    _driver.pollForJobState(TIMEOUT_WORKFLOW_NAME, TaskUtil.getNamespacedJobName(TIMEOUT_WORKFLOW_NAME, TIMEOUT_JOB_1), TaskState.TIMED_OUT);
    _driver.pollForJobState(TIMEOUT_WORKFLOW_NAME, TaskUtil.getNamespacedJobName(TIMEOUT_WORKFLOW_NAME, TIMEOUT_JOB_2), TaskState.TIMED_OUT);
    _driver.pollForWorkflowState(TIMEOUT_WORKFLOW_NAME, TaskState.FAILED);
    JobContext jobContext = _driver.getJobContext(TaskUtil.getNamespacedJobName(TIMEOUT_WORKFLOW_NAME, TIMEOUT_JOB_1));
    for (int pId : jobContext.getPartitionSet()) {
        if (jobContext.getAssignedParticipant(pId) != null) {
            // All tasks stuck at INIT->RUNNING, and state transition cancelled and marked TASK_ABORTED
            Assert.assertEquals(jobContext.getPartitionState(pId), TaskPartitionState.TASK_ABORTED);
        }
    }
    jobContext = _driver.getJobContext(TaskUtil.getNamespacedJobName(TIMEOUT_WORKFLOW_NAME, TIMEOUT_JOB_2));
    for (int pId : jobContext.getPartitionSet()) {
        if (jobContext.getAssignedParticipant(pId) != null) {
            // All tasks stuck at INIT->RUNNING, and state transition cancelled and marked TASK_ABORTED
            Assert.assertEquals(jobContext.getPartitionState(pId), TaskPartitionState.TASK_ABORTED);
        }
    }
}

/**
 * Tests that no Participants have more tasks from the same job than is specified in the config.
 * (MaxConcurrentTaskPerInstance, default value = 1)
 * NOTE: this test is supposed to generate a lot of Participant-side ERROR message (ZkClient
 * already closed!) because we are disconnecting them on purpose.
 */
@Test
public void testNoDoubleAssign() throws InterruptedException {
    // Some arbitrary workload that creates a reasonably large amount of tasks
    int workload = 10;
    // Create a workflow with jobs and tasks
    String workflowName = TestHelper.getTestMethodName();
    Workflow.Builder builder = new Workflow.Builder(workflowName);
    for (int i = 0; i < workload; i++) {
        List<TaskConfig> taskConfigs = new ArrayList<>();
        for (int j = 0; j < workload; j++) {
            String taskID = "JOB_" + i + "_TASK_" + j;
            TaskConfig.Builder taskConfigBuilder = new TaskConfig.Builder();
            taskConfigBuilder.setTaskId(taskID).setCommand(MockTask.TASK_COMMAND).addConfig(MockTask.JOB_DELAY, TASK_DURATION);
            taskConfigs.add(taskConfigBuilder.build());
        }
        String jobName = "JOB_" + i;
        // Add the namespaced job name
        _jobNames.add(workflowName + "_" + jobName);
        JobConfig.Builder jobBuilder = new JobConfig.Builder().setCommand(MockTask.TASK_COMMAND).setMaxAttemptsPerTask(10000).setJobCommandConfigMap(WorkflowGenerator.DEFAULT_COMMAND_CONFIG).addTaskConfigs(taskConfigs).setIgnoreDependentJobFailure(true).setFailureThreshold(100000).setJobCommandConfigMap(ImmutableMap.of(MockTask.JOB_DELAY, TASK_DURATION));
        builder.addJob(jobName, jobBuilder);
    }
    // Start the workflow
    _driver.start(builder.build());
    _driver.pollForWorkflowState(workflowName, TaskState.IN_PROGRESS);
    breakConnection();
    pollForDoubleAssign();
    _driver.pollForWorkflowState(workflowName, TaskState.COMPLETED);
    // Shut down thread pools
    _executorServicePoll.shutdown();
    _executorServiceConnection.shutdown();
    try {
        if (!_executorServicePoll.awaitTermination(60, TimeUnit.SECONDS)) {
            _executorServicePoll.shutdownNow();
        }
        if (!_executorServiceConnection.awaitTermination(60, TimeUnit.SECONDS)) {
            _executorServiceConnection.shutdownNow();
        }
    } catch (InterruptedException e) {
        _executorServicePoll.shutdownNow();
        _executorServiceConnection.shutdownNow();
    }
    Thread.sleep(500L);
    Assert.assertFalse(_existsDoubleAssign.get());
}

