    // Try to run 10 jobs that complete
    int numJobs = 10;
    for (int i = 0; i < numJobs; i++) {
        List<TaskConfig> taskConfigs = new ArrayList<>();
        taskConfigs.add(new TaskConfig("CompleteTask", new HashMap<String, String>()));
        JobConfig.Builder jobConfigBulider = new JobConfig.Builder().setCommand("Dummy").addTaskConfigs(taskConfigs).setJobCommandConfigMap(new HashMap<String, String>());
        workflowBuilder_2.addJob("JOB" + i, jobConfigBulider);
    }
    // If these jobs complete successfully, then that means there is no thread leak
    _driver.start(workflowBuilder_2.build());
    Assert.assertEquals(_driver.pollForWorkflowState(workflowName_2, TaskState.COMPLETED), TaskState.COMPLETED);
}

