@Test
public void testWorkflowJobFail() throws Exception {
    String workflowName = TestHelper.getTestMethodName();
    String job1 = JOB_NAME + "1";
    String job2 = JOB_NAME + "2";
    String job3 = JOB_NAME + "3";
    String job4 = JOB_NAME + "4";
    long workflowExpiry = 10000;
    long timeout = 10000;
    JobConfig.Builder jobBuilder = createJobConfigBuilder(workflowName, false, 1);
    JobConfig.Builder failedJobBuilder = createJobConfigBuilder(workflowName, true, 1);
    Workflow.Builder workflowBuilder = new Workflow.Builder(workflowName).setWorkflowConfig(new WorkflowConfig.Builder(workflowName).setWorkFlowType(WORKFLOW_TYPE).setTimeout(timeout).setParallelJobs(4).setFailureThreshold(1).build()).addJob(job1, jobBuilder).addJob(job2, jobBuilder).addJob(job3, failedJobBuilder).addJob(job4, jobBuilder).addParentChildDependency(job1, job2).addParentChildDependency(job1, job3).addParentChildDependency(job2, job4).addParentChildDependency(job3, job4).setExpiry(workflowExpiry);
    _driver.start(workflowBuilder.build());
    _driver.pollForWorkflowState(workflowName, 10000L, TaskState.FAILED);
    // Timeout is longer than fail time, so the failover should occur earlier
    WorkflowContext context = _driver.getWorkflowContext(workflowName);
    Assert.assertTrue(context.getFinishTime() - context.getStartTime() < timeout);
    // job1 will complete
    _driver.pollForJobState(workflowName, getJobNameToPoll(workflowName, job1), 10000L, TaskState.COMPLETED);
    // Possible race between 2 and 3 so it's likely for job2 to stay in either COMPLETED or ABORTED
    _driver.pollForJobState(workflowName, getJobNameToPoll(workflowName, job2), 10000L, TaskState.COMPLETED, TaskState.ABORTED);
    // job3 meant to fail
    _driver.pollForJobState(workflowName, getJobNameToPoll(workflowName, job3), 10000L, TaskState.FAILED);
    // because job4 has dependency over job3, it will fail as well
    _driver.pollForJobState(workflowName, getJobNameToPoll(workflowName, job4), 10000L, TaskState.FAILED);
    // Check MBean is updated
    ObjectName objectName = getWorkflowMBeanObjectName(workflowName);
    Assert.assertEquals((long) beanServer.getAttribute(objectName, "FailedWorkflowCount"), 1);
    // For a failed workflow, after timing out, it will be purged
    Thread.sleep(workflowExpiry + 200);
    verifyWorkflowCleanup(workflowName, getJobNameToPoll(workflowName, job1), getJobNameToPoll(workflowName, job2), getJobNameToPoll(workflowName, job3), getJobNameToPoll(workflowName, job4));
}

