        Assert.assertEquals(capacityProvider.getParticipantUsage(instance), usage.get(instance).intValue());
    }
    // persist get values back
    capacityProvider.persistCapacity();
    capacityProvider = new ZkBasedCapacityProvider(ZK_ADDR, CLUSTER_NAME, "Test");
    for (String instance : instanceNames) {
        Assert.assertEquals(capacityProvider.getParticipantCapacity(instance), capacity.get(instance).intValue());
        Assert.assertEquals(capacityProvider.getParticipantUsage(instance), usage.get(instance).intValue());
    }
    // update usage
