    capacityProvider.updateCapacity(capacity, Collections.EMPTY_MAP, 0);
    PartitionWeightAwareEvennessConstraint evenConstraint = new PartitionWeightAwareEvennessConstraint(weightProvider, capacityProvider);
    // Assume existing assignment
    ResourcesStateMap existingAssignment = new ResourcesStateMap();
    String targetResource = resourceNames.get(0);
    for (String partition : partitions) {
        for (int i = 0; i < nReplicas; i++) {
            existingAssignment.setState(targetResource, new Partition(partition), instanceNames.get(i), topState);
        }
    }
    WeightAwareRebalanceUtil util = new WeightAwareRebalanceUtil(clusterConfig, instanceConfigs);
    // INCREMENTAL
    ResourcesStateMap assignment = util.buildIncrementalRebalanceAssignment(resourceConfigs, existingAssignment, Collections.EMPTY_LIST, Collections.<AbstractRebalanceSoftConstraint>singletonList(evenConstraint));
    // check if the existingAssignment is changed
    for (String partition : partitions) {
        Assert.assertTrue(assignment.getInstanceStateMap(targetResource, new Partition(partition)).keySet().containsAll(instanceNames.subList(0, nReplicas)));
    }
    // still need to check for balance
    Map<String, Integer> weightCount = checkPartitionUsage(assignment, weightProvider);
    int max = Collections.max(weightCount.values());
    int min = Collections.min(weightCount.values());
    // Since the accuracy of Default evenness constraint is 0.01, diff should be 1/100 of participant capacity in max.
    Assert.assertTrue((max - min) <= defaultCapacity / 100);
    // FULL
    assignment = util.buildFullRebalanceAssignment(resourceConfigs, existingAssignment, Collections.EMPTY_LIST, Collections.<AbstractRebalanceSoftConstraint>singletonList(evenConstraint));
    // check if the existingAssignment is changed
    for (String partition : partitions) {
        Assert.assertFalse(assignment.getInstanceStateMap(targetResource, new Partition(partition)).keySet().containsAll(instanceNames.subList(0, nReplicas)));
    }
}

@Test(dependsOnMethods = "testRebalanceUsingZkDataProvider")
public void testInvalidInput() {
    // capacity / weight
    Map<String, Integer> capacity = new HashMap<>();
    for (String instance : instanceNames) {
        capacity.put(instance, defaultCapacity);
    }
    ZkBasedPartitionWeightProvider weightProvider = new ZkBasedPartitionWeightProvider(ZK_ADDR, CLUSTER_NAME, "QPS");
    weightProvider.updateWeights(Collections.EMPTY_MAP, Collections.EMPTY_MAP, resourceWeight);
    ZkBasedCapacityProvider capacityProvider = new ZkBasedCapacityProvider(ZK_ADDR, CLUSTER_NAME, "QPS");
    capacityProvider.updateCapacity(capacity, Collections.EMPTY_MAP, 0);
    TotalCapacityConstraint capacityConstraint = new TotalCapacityConstraint(weightProvider, capacityProvider);
    WeightAwareRebalanceUtil util = new WeightAwareRebalanceUtil(clusterConfig, instanceConfigs);
    // Empty constraint
    try {
        util.buildIncrementalRebalanceAssignment(resourceConfigs, null, Collections.EMPTY_LIST, Collections.EMPTY_LIST);
        Assert.fail("Should fail due to empty constraint list.");
    } catch (HelixException ex) {
        // expected
    }
    ResourceConfig.Builder invalidResourceBuilder = new ResourceConfig.Builder("InvalidResource");
    invalidResourceBuilder.setStateModelDefRef("OnlineOffline");
    invalidResourceBuilder.setNumPartitions(nPartitions);
    invalidResourceBuilder.setNumReplica(nReplicas);
    for (String partition : partitions) {
        invalidResourceBuilder.setPreferenceList(partition, Collections.EMPTY_LIST);
    }
    // Auto mode resource config
    try {
        invalidResourceBuilder.setRebalanceConfig(new RebalanceConfig(new ZNRecord("InvalidResource")));
        invalidResourceBuilder.getRebalanceConfig().setRebalanceMode(RebalanceConfig.RebalanceMode.FULL_AUTO);
        util.buildIncrementalRebalanceAssignment(Collections.singletonList(invalidResourceBuilder.build()), null, Collections.<AbstractRebalanceHardConstraint>singletonList(capacityConstraint), Collections.EMPTY_LIST);
        Assert.fail("Should fail due to full auto resource config.");
    } catch (HelixException ex) {
        // expected
        invalidResourceBuilder.getRebalanceConfig().setRebalanceMode(RebalanceConfig.RebalanceMode.CUSTOMIZED);
    }
    // Auto mode resource config
    try {
        invalidResourceBuilder.setStateModelDefRef("CustomizedOnlineOffline");
        util.buildIncrementalRebalanceAssignment(Collections.singletonList(invalidResourceBuilder.build()), null, Collections.<AbstractRebalanceHardConstraint>singletonList(capacityConstraint), Collections.EMPTY_LIST);
        Assert.fail("Should fail due to unknown state model def ref.");
    } catch (IllegalArgumentException ex) {
        // expected
        util.registerCustomizedStateModelDef("CustomizedOnlineOffline", OnlineOfflineSMD.build());
        ResourcesStateMap assignment = util.buildIncrementalRebalanceAssignment(Collections.singletonList(invalidResourceBuilder.build()), null, Collections.<AbstractRebalanceHardConstraint>singletonList(capacityConstraint), Collections.EMPTY_LIST);
        checkPartitionUsage(assignment, weightProvider);
    }
}

