        String instanceName = PARTICIPANT_PREFIX + "_" + (START_PORT + i);
        _setupTool.getClusterManagementTool().enableInstance(CLUSTER_NAME, instanceName, true);
    }
    Thread.sleep(1000);
    updateMetrics();
    Assert.assertEquals(_beanValueMap.get(PARTITION_COUNT), 5L);
