    Assert.assertEquals(_beanValueMap.get(WITHOUT_TOPSTATE_COUNT), 0L);
    Assert.assertEquals(_beanValueMap.get(IS_EV_MISMATCH_COUNT), 0L);
    // Drop the resource and check that all metrics are zero.
