    Thread.sleep(1000);
    updateMetrics();
    Assert.assertEquals(_beanValueMap.get(PARTITION_COUNT), 0L);
    Assert.assertEquals(_beanValueMap.get(ERROR_PARTITION_COUNT), 0L);
    Assert.assertEquals(_beanValueMap.get(WITHOUT_TOPSTATE_COUNT), 0L);
