@Test
public void testMBeanRegisteration() throws JMException {
    Set<HelixCallbackMonitor> monitors = new HashSet<>();
    for (HelixConstants.ChangeType changeType : HelixConstants.ChangeType.values()) {
        monitors.add(new HelixCallbackMonitor(TEST_TYPE, TEST_CLUSTER, null, changeType).register());
        Assert.assertTrue(_beanServer.isRegistered(buildObjectName(TEST_TYPE, TEST_CLUSTER, changeType)));
    }
    for (HelixConstants.ChangeType changeType : HelixConstants.ChangeType.values()) {
        monitors.add(new HelixCallbackMonitor(TEST_TYPE, TEST_CLUSTER, null, changeType).register());
        Assert.assertTrue(_beanServer.isRegistered(buildObjectName(TEST_TYPE, TEST_CLUSTER, changeType, 1)));
    }
    for (HelixConstants.ChangeType changeType : HelixConstants.ChangeType.values()) {
        monitors.add(new HelixCallbackMonitor(TEST_TYPE, TEST_CLUSTER, null, changeType).register());
        Assert.assertTrue(_beanServer.isRegistered(buildObjectName(TEST_TYPE, TEST_CLUSTER, changeType, 2)));
    }
    // Un-register all monitors
    for (HelixCallbackMonitor monitor : monitors) {
        monitor.unregister();
    }
    for (HelixConstants.ChangeType changeType : HelixConstants.ChangeType.values()) {
        Assert.assertFalse(_beanServer.isRegistered(buildObjectName(TEST_TYPE, TEST_CLUSTER, changeType)));
        Assert.assertFalse(_beanServer.isRegistered(buildObjectName(TEST_TYPE, TEST_CLUSTER, changeType, 1)));
