/**
 * Tests the duality of two AssignableInstanceManager instances to model the
 * situation where there is a Controller switch and AssignableInstanceManager is
 * built back from scratch.
 * @throws InterruptedException
 */
@Test
public void testControllerSwitch() throws InterruptedException {
    setupAndRunJobs();
    Map<String, LiveInstance> liveInstanceMap = new HashMap<>();
    Map<String, InstanceConfig> instanceConfigMap = new HashMap<>();
    RoutingTableProvider routingTableProvider = new RoutingTableProvider(_manager);
    Collection<LiveInstance> liveInstances = routingTableProvider.getLiveInstances();
    for (LiveInstance liveInstance : liveInstances) {
        String instanceName = liveInstance.getInstanceName();
        liveInstanceMap.put(instanceName, liveInstance);
        instanceConfigMap.put(instanceName, _gSetupTool.getClusterManagementTool().getInstanceConfig(CLUSTER_NAME, instanceName));
    }
    // Get ClusterConfig
    ClusterConfig clusterConfig = _manager.getConfigAccessor().getClusterConfig(CLUSTER_NAME);
    // Initialize TaskDataCache
    HelixDataAccessor accessor = _manager.getHelixDataAccessor();
    TaskDataCache taskDataCache = new TaskDataCache(CLUSTER_NAME);
    Map<String, ResourceConfig> resourceConfigMap = accessor.getChildValuesMap(accessor.keyBuilder().resourceConfigs(), true);
    // Wait for the job pipeline
    Thread.sleep(1000);
    taskDataCache.refresh(accessor, resourceConfigMap);
    // Create prev manager and build
    AssignableInstanceManager prevAssignableInstanceManager = new AssignableInstanceManager();
    prevAssignableInstanceManager.buildAssignableInstances(clusterConfig, taskDataCache, liveInstanceMap, instanceConfigMap);
    Map<String, AssignableInstance> prevAssignableInstanceMap = new HashMap<>(prevAssignableInstanceManager.getAssignableInstanceMap());
    Map<String, TaskAssignResult> prevTaskAssignResultMap = new HashMap<>(prevAssignableInstanceManager.getTaskAssignResultMap());
    // Generate a new AssignableInstanceManager
    taskDataCache.refresh(accessor, resourceConfigMap);
    AssignableInstanceManager newAssignableInstanceManager = new AssignableInstanceManager();
    newAssignableInstanceManager.buildAssignableInstances(clusterConfig, taskDataCache, liveInstanceMap, instanceConfigMap);
    Map<String, AssignableInstance> newAssignableInstanceMap = new HashMap<>(newAssignableInstanceManager.getAssignableInstanceMap());
    Map<String, TaskAssignResult> newTaskAssignResultMap = new HashMap<>(newAssignableInstanceManager.getTaskAssignResultMap());
    // Compare prev and new - they should match up exactly
    Assert.assertEquals(prevAssignableInstanceMap.size(), newAssignableInstanceMap.size());
    Assert.assertEquals(prevTaskAssignResultMap.size(), newTaskAssignResultMap.size());
    for (Map.Entry<String, AssignableInstance> assignableInstanceEntry : newAssignableInstanceMap.entrySet()) {
        String instance = assignableInstanceEntry.getKey();
        Assert.assertEquals(prevAssignableInstanceMap.get(instance).getCurrentAssignments(), assignableInstanceEntry.getValue().getCurrentAssignments());
        Assert.assertEquals(prevAssignableInstanceMap.get(instance).getTotalCapacity(), assignableInstanceEntry.getValue().getTotalCapacity());
        Assert.assertEquals(prevAssignableInstanceMap.get(instance).getUsedCapacity(), assignableInstanceEntry.getValue().getUsedCapacity());
    }
    for (Map.Entry<String, TaskAssignResult> taskAssignResultEntry : newTaskAssignResultMap.entrySet()) {
        String taskID = taskAssignResultEntry.getKey();
        Assert.assertEquals(prevTaskAssignResultMap.get(taskID).toString(), taskAssignResultEntry.getValue().toString());
    }
    // Shut down RoutingTableProvider so periodic update gets shut down
    routingTableProvider.shutdown();
}

@Test
public void testCleanExpiredJobs() throws Exception {
    String queue = TestHelper.getTestMethodName();
    JobQueue.Builder builder = TaskTestUtil.buildJobQueue(queue);
    JobConfig.Builder jobBuilder = new JobConfig.Builder().setTargetResource(WorkflowGenerator.DEFAULT_TGT_DB).setCommand(MockTask.TASK_COMMAND).setMaxAttemptsPerTask(2).setJobCommandConfigMap(WorkflowGenerator.DEFAULT_COMMAND_CONFIG).setExpiry(1L);
