        TaskUtil.setJobContext(_manager, TaskUtil.getNamespacedJobName(queue, "JOB" + i), TaskTestUtil.buildJobContext(startTime, startTime, TaskPartitionState.COMPLETED));
    }
    for (int i = 4; i < 6; i++) {
