    // Create 5 jobs with 1 WriteTask each
    for (int i = 0; i < NUM_JOB; i++) {
        List<TaskConfig> taskConfigs = new ArrayList<>();
        taskConfigs.add(new TaskConfig("WriteTask", new HashMap<String, String>()));
        JobConfig.Builder jobConfigBulider = new JobConfig.Builder().setCommand(JOB_COMMAND).addTaskConfigs(taskConfigs).setJobCommandConfigMap(_jobCommandMap);
        String jobName = "JOB" + i;
        String taskPartitionId = "0";
        workflowBuilder.addJob(jobName, jobConfigBulider);
        recordMap.put(jobName, new TaskRecord(workflowName, jobName, taskPartitionId));
    }
    // Start the workflow and wait for all tasks started
    _driver.start(workflowBuilder.build());
    allTasksReady.await();
    // add "workflow":"workflow" to the workflow's user content
    _driver.addOrUpdateWorkflowUserContentMap(workflowName, Collections.singletonMap(workflowName, workflowName));
    for (TaskRecord rec : recordMap.values()) {
        // add "job":"job" to the job's user content
        String namespacedJobName = TaskUtil.getNamespacedJobName(rec.workflowName, rec.jobName);
        _driver.addOrUpdateJobUserContentMap(rec.workflowName, rec.jobName, Collections.singletonMap(namespacedJobName, namespacedJobName));
        String namespacedTaskName = TaskUtil.getNamespacedTaskName(namespacedJobName, rec.taskPartitionId);
        // add "taskId":"taskId" to the task's user content
        _driver.addOrUpdateTaskUserContentMap(rec.workflowName, rec.jobName, rec.taskPartitionId, Collections.singletonMap(namespacedTaskName, namespacedTaskName));
    }
    adminReady.countDown();
    _driver.pollForWorkflowState(workflowName, TaskState.COMPLETED);
    // Aggregate key-value mappings in UserContentStore
    for (TaskRecord rec : recordMap.values()) {
        Assert.assertEquals(_driver.getWorkflowUserContentMap(rec.workflowName).get(TaskDumpResultKey.WorkflowContent.name()), constructContentStoreResultString(rec.workflowName, rec.workflowName));
        String namespacedJobName = TaskUtil.getNamespacedJobName(rec.workflowName, rec.jobName);
        Assert.assertEquals(_driver.getJobUserContentMap(rec.workflowName, rec.jobName).get(TaskDumpResultKey.JobContent.name()), constructContentStoreResultString(namespacedJobName, namespacedJobName));
        String namespacedTaskName = TaskUtil.getNamespacedTaskName(namespacedJobName, rec.taskPartitionId);
        Assert.assertEquals(_driver.getTaskUserContentMap(rec.workflowName, rec.jobName, rec.taskPartitionId).get(TaskDumpResultKey.TaskContent.name()), constructContentStoreResultString(namespacedTaskName, namespacedTaskName));
    }
}

