/**
 * Test "update" command for updateInstanceConfig endpoint.
 * @throws IOException
 */
@Test(dependsOnMethods = "updateInstance")
public void updateInstanceConfig() throws IOException {
    System.out.println("Start test :" + TestHelper.getTestMethodName());
    String instanceName = CLUSTER_NAME + "localhost_12918";
    InstanceConfig instanceConfig = _configAccessor.getInstanceConfig(CLUSTER_NAME, instanceName);
    ZNRecord record = instanceConfig.getRecord();
    // Generate a record containing three keys (k0, k1, k2) for all fields
    String value = "value";
    for (int i = 0; i < 3; i++) {
        String key = "k" + i;
        record.getSimpleFields().put(key, value);
        record.getMapFields().put(key, ImmutableMap.of(key, value));
        record.getListFields().put(key, Arrays.asList(key, value));
    }
    // 1. Add these fields by way of "update"
    Entity entity = Entity.entity(OBJECT_MAPPER.writeValueAsString(record), MediaType.APPLICATION_JSON_TYPE);
    post("clusters/" + CLUSTER_NAME + "/instances/" + instanceName + "/configs", Collections.singletonMap("command", "update"), entity, Response.Status.OK.getStatusCode());
    // Check that the fields have been added
    Assert.assertEquals(record.getSimpleFields(), _configAccessor.getInstanceConfig(CLUSTER_NAME, instanceName).getRecord().getSimpleFields());
    Assert.assertEquals(record.getListFields(), _configAccessor.getInstanceConfig(CLUSTER_NAME, instanceName).getRecord().getListFields());
    Assert.assertEquals(record.getMapFields(), _configAccessor.getInstanceConfig(CLUSTER_NAME, instanceName).getRecord().getMapFields());
    String newValue = "newValue";
    // 2. Modify the record and update
    for (int i = 0; i < 3; i++) {
        String key = "k" + i;
        record.getSimpleFields().put(key, newValue);
        record.getMapFields().put(key, ImmutableMap.of(key, newValue));
        record.getListFields().put(key, Arrays.asList(key, newValue));
    }
    entity = Entity.entity(OBJECT_MAPPER.writeValueAsString(record), MediaType.APPLICATION_JSON_TYPE);
    post("clusters/" + CLUSTER_NAME + "/instances/" + instanceName + "/configs", Collections.singletonMap("command", "update"), entity, Response.Status.OK.getStatusCode());
    // Check that the fields have been modified
    Assert.assertEquals(record.getSimpleFields(), _configAccessor.getInstanceConfig(CLUSTER_NAME, instanceName).getRecord().getSimpleFields());
    Assert.assertEquals(record.getListFields(), _configAccessor.getInstanceConfig(CLUSTER_NAME, instanceName).getRecord().getListFields());
    Assert.assertEquals(record.getMapFields(), _configAccessor.getInstanceConfig(CLUSTER_NAME, instanceName).getRecord().getMapFields());
}

