 */
@Test(dependsOnMethods = "updateInstanceConfig")
public void deleteInstanceConfig() throws IOException {
    System.out.println("Start test :" + TestHelper.getTestMethodName());
    String instanceName = CLUSTER_NAME + "localhost_12918";
    ZNRecord record = new ZNRecord(instanceName);
    // Generate a record containing three keys (k1, k2, k3) for all fields for deletion
    String value = "value";
    for (int i = 1; i < 4; i++) {
        String key = "k" + i;
        record.getSimpleFields().put(key, value);
        record.getMapFields().put(key, ImmutableMap.of(key, value));
        record.getListFields().put(key, Arrays.asList(key, value));
    }
    // First, add these fields by way of "update"
    Entity entity = Entity.entity(OBJECT_MAPPER.writeValueAsString(record), MediaType.APPLICATION_JSON_TYPE);
    post("clusters/" + CLUSTER_NAME + "/instances/" + instanceName + "/configs", Collections.singletonMap("command", "delete"), entity, Response.Status.OK.getStatusCode());
    // Check that the keys k1 and k2 have been deleted, and k0 remains
    for (int i = 0; i < 4; i++) {
        String key = "k" + i;
        if (i == 0) {
            Assert.assertTrue(_configAccessor.getInstanceConfig(CLUSTER_NAME, instanceName).getRecord().getSimpleFields().containsKey(key));
            Assert.assertTrue(_configAccessor.getInstanceConfig(CLUSTER_NAME, instanceName).getRecord().getListFields().containsKey(key));
            Assert.assertTrue(_configAccessor.getInstanceConfig(CLUSTER_NAME, instanceName).getRecord().getMapFields().containsKey(key));
            continue;
        }
        Assert.assertFalse(_configAccessor.getInstanceConfig(CLUSTER_NAME, instanceName).getRecord().getSimpleFields().containsKey(key));
        Assert.assertFalse(_configAccessor.getInstanceConfig(CLUSTER_NAME, instanceName).getRecord().getListFields().containsKey(key));
        Assert.assertFalse(_configAccessor.getInstanceConfig(CLUSTER_NAME, instanceName).getRecord().getMapFields().containsKey(key));
    }
}

